import * as THREE from 'three';
import {armCurveWeight,footWeight} from '../dormi-sports-pose.js';
import {createAimingDeformer,fitPalmPrimitive} from './aiming-deformer.js';
import {LASER_GEOMETRY as G} from './laser-layout.js';
const sides=['left','right'],sign=s=>s==='left'?-1:1,copy=x=>structuredClone(x);
/** Borrows the poser-owned original vertices and calibrates against real palm surfaces. */
export function createLaserRig({model,poser}={}){
 if(!model?.isObject3D||!poser?.setPose||!poser?.getState)throw TypeError('Laser requires original actor');
 const pose=poser.getState(),saved=[],records=[],hands={left:[],right:[]},armSurfaces={left:[],right:[]},handRefs={left:[],right:[]},soleRefs={left:[],right:[]},soles={left:[],right:[]},face=[],deformer=createAimingDeformer(),v=new THREE.Vector3();let alive=true,last=null,applications=0;
 model.traverse(mesh=>{if(mesh.isMesh)saved.push({mesh,g:mesh.geometry,p:mesh.geometry.attributes.position.array.slice(),n:mesh.geometry.attributes.normal?.array.slice(),box:mesh.geometry.boundingBox?.clone(),sphere:mesh.geometry.boundingSphere?.clone()});});
 function restore(){poser.setPose(pose.name,pose.amount,pose.time);for(const r of saved){r.mesh.geometry=r.g;r.g.attributes.position.array.set(r.p);r.g.attributes.position.needsUpdate=true;if(r.n){r.g.attributes.normal.array.set(r.n);r.g.attributes.normal.needsUpdate=true;}r.g.boundingBox=r.box?.clone()??null;r.g.boundingSphere=r.sphere?.clone()??null;}}
 try{poser.setPose('stand',0,0);model.updateWorldMatrix(true,true);const inverse=model.matrixWorld.clone().invert();for(const r of saved){const matrix=inverse.clone().multiply(r.mesh.matrixWorld),a=r.g.attributes.position,rest=new Float32Array(a.count*3),active=[];for(let i=0;i<a.count;i++){v.fromBufferAttribute(a,i).applyMatrix4(matrix);rest.set(v.toArray(),i*3);if(['Dormi_body','Navy_belly_spiral','Belly_spiral_rounded_tip'].includes(r.mesh.name)&&(armCurveWeight(v.x,v.y)>0||footWeight(v.x,v.y,v.z)>0))active.push(i);if(r.mesh.name==='Dormi_body'){const s=v.x<0?'left':'right';if(armCurveWeight(v.x,v.y)>0)armSurfaces[s].push(v.clone());if(Math.abs(v.x)>.59&&v.y<.39&&v.y>.28){hands[s].push(v.clone());handRefs[s].push({mesh:r.mesh,index:i});}if(v.y<.002&&Math.abs(v.x)>.1&&Math.abs(v.x)<.36){soles[s].push(v.clone());soleRefs[s].push({mesh:r.mesh,index:i});}}if(/face|eye|cheek|antenna|smile|tongue/i.test(r.mesh.name))face.push(v.clone());}records.push({...r,rest,active,fromRoot:matrix.clone().invert()});}if(sides.some(s=>!hands[s].length||!soles[s].length))throw Error('Original palms/soles missing');}catch(e){restore();throw e;}
 function setup(f){
  const guard=f.guard??1,quaternion=new THREE.Quaternion().setFromEuler(new THREE.Euler(-(f.pitch??.035),f.yaw??.025,0,'YXZ')),direction=new THREE.Vector3(0,0,1).applyQuaternion(quaternion),axis=new THREE.Vector3(0,1,0).applyQuaternion(quaternion),rotations={},feet={};
  for(const s of sides){const rotation=new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(0,0,1),sign(s)*Math.PI/2).multiply(new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(0,1,0),-sign(s)*Math.PI/2));rotation.premultiply(quaternion);rotations[s]=new THREE.Quaternion().slerp(rotation,guard);}
  for(const s of sides){const p=f.feet[s];feet[s]=[p.x-f.root.x-sign(s)*.21,p.y-f.root.y,p.z-f.root.z];}deformer.setFrame({rotations,footOffsets:feet});
  const left=hands.left.map(p=>deformer.deform(p.x,p.y,p.z,new THREE.Vector3())),right=hands.right.map(p=>deformer.deform(p.x,p.y,p.z,new THREE.Vector3()));
  return{quaternion,direction,grip:fitPalmPrimitive(left,direction,axis,G.gripRadius,G.gripHeight,armSurfaces.left.map(p=>deformer.deform(p.x,p.y,p.z,new THREE.Vector3()))),rear:fitPalmPrimitive(right,direction,axis,G.rearGripRadius,null,armSurfaces.right.map(p=>deformer.deform(p.x,p.y,p.z,new THREE.Vector3())))};
 }
 function fit(f){const c=setup(f),offset=new THREE.Vector3(f.root.x,f.root.y,f.root.z);return{grip:c.grip.clone().add(offset),rear:c.rear.clone().add(offset),quaternion:c.quaternion.clone(),direction:c.direction.clone(),beam:f.beam??null};}
 function apply(f){if(!alive)throw Error('Laser rig released');setup(f);for(const r of records){if(!r.active.length)continue;const a=r.g.attributes.position;for(const i of r.active){const k=i*3;deformer.deform(r.rest[k],r.rest[k+1],r.rest[k+2],v).applyMatrix4(r.fromRoot);a.setXYZ(i,v.x,v.y,v.z);}a.needsUpdate=true;r.g.computeVertexNormals();r.g.computeBoundingBox();r.g.computeBoundingSphere();}last=copy(f);applications++;return last;}
 function probe(f,station){setup(f);model.updateWorldMatrix(true,true);station.machine.updateWorldMatrix(true,true);const root=new THREE.Matrix4().makeTranslation(f.root.x,f.root.y,f.root.z),to=(node)=>node.matrixWorld.clone().invert().multiply(station.machine.matrixWorld).multiply(root),toGrip=to(station.grip),toRear=to(station.rearGrip),toMat=to(station.mat);let handGap=Infinity,secondHandGap=Infinity,supportGap=0,faceClearance=Infinity;for(const ref of handRefs.left){v.fromBufferAttribute(ref.mesh.geometry.attributes.position,ref.index).applyMatrix4(ref.mesh.matrixWorld).applyMatrix4(station.grip.matrixWorld.clone().invert());handGap=Math.min(handGap,Math.max(Math.hypot(v.x,v.z)-G.gripRadius,Math.abs(v.y)-G.gripHeight/2));}for(const ref of handRefs.right){v.fromBufferAttribute(ref.mesh.geometry.attributes.position,ref.index).applyMatrix4(ref.mesh.matrixWorld).applyMatrix4(station.rearGrip.matrixWorld.clone().invert());secondHandGap=Math.min(secondHandGap,v.length()-G.rearGripRadius);}for(const s of sides){let bottom=Infinity;for(const ref of soleRefs[s]){v.fromBufferAttribute(ref.mesh.geometry.attributes.position,ref.index).applyMatrix4(ref.mesh.matrixWorld).applyMatrix4(station.mat.matrixWorld.clone().invert());const size=station.mat.geometry.parameters;if(Math.abs(v.x)<=size.width/2&&Math.abs(v.z)<=size.depth/2)bottom=Math.min(bottom,v.y-size.height/2);}supportGap=Math.max(supportGap,Math.abs(bottom));}for(const p of face){v.copy(p).applyMatrix4(toGrip);faceClearance=Math.min(faceClearance,Math.hypot(v.x,v.z)-G.gripRadius);}const muzzle=station.machine.worldToLocal(station.muzzle.getWorldPosition(new THREE.Vector3())),direction=new THREE.Vector3(0,0,1).applyQuaternion(station.muzzle.getWorldQuaternion(new THREE.Quaternion())).transformDirection(station.machine.matrixWorld.clone().invert());return{muzzle:{x:muzzle.x,y:muzzle.y,z:muzzle.z},direction:{x:direction.x,y:direction.y,z:direction.z},handGap,secondHandGap,supportGap,faceClearance};}
 return{apply,fit,probe,getFrame:()=>last,release({restore:doRestore=true}={}){if(!alive)return;if(doRestore)restore();alive=false;last=null;},diagnostics:()=>({actorClones:0,newGeometries:0,newMaterials:0,applications,handVertices:hands.left.length+hands.right.length,released:!alive})};
}
